screenPanels.initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector("#history-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const detailOverlay = container.querySelector("#detail-overlay");
  const detailContent = container.querySelector("#detail-content");
  const closeDetailBtn = container.querySelector("#close-detail");

  // ステータスバッジの色分け
  function getStatusBadge(status) {
    const colors = {
      "未検証": { bg: "rgba(255,152,0,0.15)", text: "#ffb74d", label: "未検証" },
      "検証済み": { bg: "rgba(76,175,80,0.15)", text: "#81c784", label: "検証済み" },
      "不一致": { bg: "rgba(244,67,54,0.15)", text: "#ef5350", label: "不一致" }
    };
    const color = colors[status] || colors["未検証"];
    return `<span style="background: ${color.bg}; color: ${color.text}; padding: 4px 8px; border-radius: 3px; font-size: 11px; font-weight: 600;">${color.label}</span>`;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const contractId = r.contract_id || r.contractId || "—";
      const customerName = r.customer_name || r.customerName || "—";
      const changeType = r.change_type || r.changeType || "—";
      const changeField = r.change_field || r.changeField || "—";
      const beforeValue = (r.before_value || r.beforeValue || "—").substring(0, 30);
      const afterValue = (r.after_value || r.afterValue || "—").substring(0, 30);
      const verifyStatus = r.verification_status || r.verificationStatus || "未検証";

      return `
        <tr 
          data-id="${r.id}" 
          style="
            border-bottom: 1px solid var(--border); 
            cursor: pointer; 
            transition: background 0.2s;
          "
          onmouseover="this.style.background='rgba(255,255,255,0.04)'"
          onmouseout="this.style.background='transparent'"
        >
          <td style="padding: 8px; color: var(--text);">${contractId}</td>
          <td style="padding: 8px; color: var(--text);">${customerName}</td>
          <td style="padding: 8px; color: var(--text);">${changeType}</td>
          <td style="padding: 8px; color: var(--text-muted); font-size: 12px;">${changeField}</td>
          <td style="padding: 8px; color: var(--text-muted); font-size: 12px;">${beforeValue}</td>
          <td style="padding: 8px; color: var(--text-muted); font-size: 12px;">${afterValue}</td>
          <td style="padding: 8px; text-align: center;">${getStatusBadge(verifyStatus)}</td>
          <td style="padding: 8px; text-align: center;">
            <button 
              class="detail-btn" 
              data-id="${r.id}" 
              style="
                background: transparent; 
                border: none; 
                color: var(--primary); 
                cursor: pointer; 
                font-size: 12px; 
                text-decoration: underline;
              "
            >
              詳細
            </button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 詳細パネルを開く
  function openDetail(row) {
    const beforeObj = (() => {
      try {
        return typeof row.before_value === "string" ? JSON.parse(row.before_value || "{}") : row.before_value || {};
      } catch {
        return { raw: row.before_value || "—" };
      }
    })();

    const afterObj = (() => {
      try {
        return typeof row.after_value === "string" ? JSON.parse(row.after_value || "{}") : row.after_value || {};
      } catch {
        return { raw: row.after_value || "—" };
      }
    })();

    detailContent.innerHTML = `
      <div style="display: flex; flex-direction: column; gap: 16px;">
        <div>
          <label style="font-size: 11px; color: var(--text-muted); font-weight: 600; text-transform: uppercase;">契約ID</label>
          <p style="margin: 4px 0 0 0; color: var(--text); font-size: 14px;">${row.contract_id || row.contractId || "—"}</p>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); font-weight: 600; text-transform: uppercase;">顧客名</label>
          <p style="margin: 4px 0 0 0; color: var(--text); font-size: 14px;">${row.customer_name || row.customerName || "—"}</p>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); font-weight: 600; text-transform: uppercase;">変更種別</label>
          <p style="margin: 4px 0 0 0; color: var(--text); font-size: 14px;">${row.change_type || row.changeType || "—"}</p>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); font-weight: 600; text-transform: uppercase;">変更フィールド</label>
          <p style="margin: 4px 0 0 0; color: var(--text); font-size: 14px;">${row.change_field || row.changeField || "—"}</p>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); font-weight: 600; text-transform: uppercase;">変更前の値</label>
          <pre style="
            margin: 4px 0 0 0; 
            color: var(--text); 
            font-size: 12px; 
            background: rgba(0,0,0,0.2); 
            padding: 8px; 
            border-radius: 3px; 
            overflow-x: auto;
            white-space: pre-wrap;
            word-break: break-word;
          ">${JSON.stringify(beforeObj, null, 2)}</pre>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); font-weight: 600; text-transform: uppercase;">変更後の値</label>
          <pre style="
            margin: 4px 0 0 0; 
            color: var(--text); 
            font-size: 12px; 
            background: rgba(0,0,0,0.2); 
            padding: 8px; 
            border-radius: 3px; 
            overflow-x: auto;
            white-space: pre-wrap;
            word-break: break-word;
          ">${JSON.stringify(afterObj, null, 2)}</pre>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); font-weight: 600; text-transform: uppercase;">検証ステータス</label>
          <p style="margin: 4px 0 0 0;">${getStatusBadge(row.verification_status || row.verificationStatus || "未検証")}</p>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); font-weight: 600; text-transform: uppercase;">変更日時</label>
          <p style="margin: 4px 0 0 0; color: var(--text); font-size: 13px;">${new Date(row.created_at || row.createdAt).toLocaleString("ja-JP")}</p>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); font-weight: 600; text-transform: uppercase;">変更者</label>
          <p style="margin: 4px 0 0 0; color: var(--text); font-size: 13px;">${row.creator_name || row.creatorName || "—"}</p>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); font-weight: 600; text-transform: uppercase;">備考</label>
          <p style="margin: 4px 0 0 0; color: var(--text); font-size: 13px; white-space: pre-wrap;">${row.remarks || row.note || "—"}</p>
        </div>
      </div>
    `;

    detailPanel.style.display = "flex";
    detailOverlay.style.display = "block";
  }

  // 詳細パネルを閉じる
  function closeDetail() {
    detailPanel.style.display = "none";
    detailOverlay.style.display = "none";
  }

  // 初期データ描画
  renderRows(tables[0]?.records || []);

  // 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", async () => {
    const contractId = container.querySelector("[data-testid='contract-id-input']").value.trim().toLowerCase();
    const customerName = container.querySelector("[data-testid='customer-name-input']").value.trim().toLowerCase();
    const changeType = container.querySelector("[data-testid='change-type-select']").value;
    const verifyStatus = container.querySelector("[data-testid='verification-status-select']").value;
    const dateFrom = container.querySelector("[data-testid='change-date-from']").value;
    const dateTo = container.querySelector("[data-testid='change-date-to']").value;

    const rows = await window.aivicApi.list(0) || tables[0]?.records || [];

    const filtered = rows.filter(r => {
      const cid = (r.contract_id || r.contractId || "").toLowerCase();
      const cname = (r.customer_name || r.customerName || "").toLowerCase();
      const ctype = r.change_type || r.changeType || "";
      const vstatus = r.verification_status || r.verificationStatus || "";
      const cdate = new Date(r.created_at || r.createdAt);
      const fromDate = dateFrom ? new Date(dateFrom) : null;
      const toDate = dateTo ? new Date(dateTo) : null;

      const matchId = !contractId || cid.includes(contractId);
      const matchName = !customerName || cname.includes(customerName);
      const matchType = !changeType || ctype === changeType;
      const matchStatus = !verifyStatus || vstatus === verifyStatus;
      const matchDateFrom = !fromDate || cdate >= fromDate;
      const matchDateTo = !toDate || cdate <= new Date(toDate.getTime() + 86400000);

      return matchId && matchName && matchType && matchStatus && matchDateFrom && matchDateTo;
    });

    renderRows(filtered);
  });

  // リセットボタン
  container.querySelector("[data-testid='reset-button']").addEventListener("click", () => {
    container.querySelector("[data-testid='contract-id-input']").value = "";
    container.querySelector("[data-testid='customer-name-input']").value = "";
    container.querySelector("[data-testid='change-type-select']").value = "";
    container.querySelector("[data-testid='verification-status-select']").value = "";
    container.querySelector("[data-testid='change-date-from']").value = "";
    container.querySelector("[data-testid='change-date-to']").value = "";
    renderRows(tables[0]?.records || []);
  });

  // CSVエクスポート
  container.querySelector("[data-testid='export-csv-button']").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0) || tables[0]?.records || [];
    const headers = ["契約ID", "顧客名", "変更種別", "変更フィールド", "変更前", "変更後", "検証ステータス", "変更日時", "変更者"];
    const csvContent = [
      "\uFEFF" + headers.join(","),
      ...rows.map(r => [
        r.contract_id || r.contractId || "",
        r.customer_name || r.customerName || "",
        r.change_type || r.changeType || "",
        r.change_field || r.changeField || "",
        (r.before_value || r.beforeValue || "").replace(/"/g, '""'),
        (r.after_value || r.afterValue || "").replace(/"/g, '""'),
        r.verification_status || r.verificationStatus || "",
        new Date(r.created_at || r.createdAt).toLocaleString("ja-JP"),
        r.creator_name || r.creatorName || ""
      ].map(v => `"${v}"`).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `contract-history-${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  });

  // 詳細ボタン（イベントデリゲーション）
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const rows = tables[0]?.records || [];
      const row = rows.find(r => r.id === id);
      if (row) openDetail(row);
    }
  });

  // 詳細パネルを閉じる
  closeDetailBtn.addEventListener("click", closeDetail);
  detailOverlay.addEventListener("click", closeDetail);
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const contractHistoryIdx = tables.findIndex(t => t.tableName === "契約履歴") ?? 0;
  const billingIdx = tables.findIndex(t => t.tableName === "請求") ?? 1;
  const contractIdx = tables.findIndex(t => t.tableName === "契約") ?? 2;
  const customerIdx = tables.findIndex(t => t.tableName === "顧客") ?? 3;

  // 初期データ
  let allContractHistory = tables[contractHistoryIdx]?.records || [];
  let allBilling = tables[billingIdx]?.records || [];
  let allContracts = tables[contractIdx]?.records || [];
  let allCustomers = tables[customerIdx]?.records || [];

  // ===== 1. 再描画関数 =====
  function renderContractHistory(rows) {
    const tbody = container.querySelector("#contract-history-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="padding: 1rem; text-align: center; color: var(--text-muted);">該当データなし</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => {
      const changeDate = r.作成日時 ? new Date(r.作成日時).toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '-';
      const changeType = r.変更種別 || '-';
      const fieldName = r.変更フィールド名 || '-';
      const beforeVal = r.変更前値 ? (typeof r.変更前値 === 'string' ? r.変更前値.substring(0, 15) : JSON.stringify(r.変更前値).substring(0, 15)) : '-';
      const afterVal = r.変更後値 ? (typeof r.変更後値 === 'string' ? r.変更後値.substring(0, 15) : JSON.stringify(r.変更後値).substring(0, 15)) : '-';
      const verifyStatus = r.請求検証ステータス || '未検証';
      const statusColor = verifyStatus === '不一致' ? '#ff9999' : verifyStatus === '検証済み' ? '#99ff99' : '#d0d0d0';
      return `<tr style="border-bottom: 1px solid rgba(255,255,255,0.08); background: ${verifyStatus === '不一致' ? 'rgba(255,100,100,0.08)' : 'transparent'};">
        <td style="padding: 0.5rem; color: var(--text);">${changeDate}</td>
        <td style="padding: 0.5rem; color: var(--text);">${changeType}</td>
        <td style="padding: 0.5rem; color: var(--text);">${fieldName}</td>
        <td style="padding: 0.5rem; text-align: right; color: var(--text-muted); font-size: 0.75rem;">${beforeVal} → ${afterVal}</td>
      </tr>`;
    }).join("");
  }

  function renderBillingHistory(rows) {
    const tbody = container.querySelector("#billing-history-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="padding: 1rem; text-align: center; color: var(--text-muted);">該当データなし</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => {
      const billingDate = r.請求日 ? new Date(r.請求日).toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit' }) : '-';
      const billingMonth = r.請求年月 || '-';
      const amount = r.請求金額 ? `¥${r.請求金額.toLocaleString()}` : '-';
      const status = r.請求ステータス || '-';
      const statusColor = status === '支払済' ? '#99ff99' : status === '延滞' ? '#ff9999' : '#d0d0d0';
      return `<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 0.5rem; color: var(--text);">${billingDate}</td>
        <td style="padding: 0.5rem; color: var(--text);">${billingMonth}</td>
        <td style="padding: 0.5rem; text-align: right; color: var(--text); font-weight: 600;">${amount}</td>
        <td style="padding: 0.5rem; color: ${statusColor}; font-weight: 500;">${status}</td>
      </tr>`;
    }).join("");
  }

  function renderTimeline(contractRows, billingRows) {
    const container_tl = container.querySelector("#timeline-container");
    if (!contractRows || !billingRows || (contractRows.length === 0 && billingRows.length === 0)) {
      container_tl.innerHTML = '<div style="text-align: center; color: var(--text-muted); padding: 1rem;">該当データなし</div>';
      return;
    }

    // イベント統合
    const events = [];
    (contractRows || []).forEach(r => {
      events.push({
        type: 'contract',
        date: r.作成日時 ? new Date(r.作成日時) : new Date(0),
        label: `契約変更: ${r.変更種別 || '更新'}`,
        detail: `${r.変更フィールド名 || '-'}: ${r.変更前値 || '-'} → ${r.変更後値 || '-'}`,
        verifyStatus: r.請求検証ステータス || '未検証'
      });
    });
    (billingRows || []).forEach(r => {
      events.push({
        type: 'billing',
        date: r.請求日 ? new Date(r.請求日) : new Date(0),
        label: `請求: ${r.請求年月 || '-'}`,
        detail: `金額: ¥${r.請求金額 ? r.請求金額.toLocaleString() : '-'} (${r.請求ステータス || '-'})`,
        verifyStatus: r.請求ステータス === '支払済' ? '検証済み' : '未検証'
      });
    });

    // 時系列ソート
    events.sort((a, b) => a.date - b.date);

    // 不整合検出（契約変更と請求の時間ズレ）
    let discrepancyCount = 0;
    const discrepancies = [];
    for (let i = 0; i < events.length - 1; i++) {
      if (events[i].type === 'contract' && events[i + 1].type === 'billing') {
        const timeDiff = Math.abs(events[i + 1].date - events[i].date) / (1000 * 60 * 60 * 24); // 日数
        if (timeDiff > 7) { // 7日以上のズレ
          discrepancyCount++;
          discrepancies.push(i);
        }
      }
    }
    container.querySelector("#discrepancy-count").textContent = `不整合: ${discrepancyCount}件`;

    // タイムライン描画
    container_tl.innerHTML = events.map((e, idx) => {
      const isDiscrepancy = discrepancies.includes(idx);
      const dateStr = e.date.toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
      const bgColor = isDiscrepancy ? 'rgba(255,100,100,0.15)' : (e.type === 'contract' ? 'rgba(100,150,255,0.08)' : 'rgba(100,200,100,0.08)');
      const borderColor = isDiscrepancy ? '#ff9999' : (e.type === 'contract' ? '#6496ff' : '#64c864');
      return `<div style="padding: 0.5rem; border-left: 3px solid ${borderColor}; background: ${bgColor}; border-radius: 3px; display: flex; justify-content: space-between; align-items: flex-start;">
        <div>
          <div style="font-weight: 600; color: var(--text);">${e.label}</div>
          <div style="font-size: 0.75rem; color: var(--text-muted); margin-top: 0.25rem;">${dateStr}</div>
          <div style="font-size: 0.75rem; color: var(--text); margin-top: 0.25rem;">${e.detail}</div>
        </div>
        ${isDiscrepancy ? `<span style="background: #ff9999; color: #fff; padding: 0.25rem 0.5rem; border-radius: 3px; font-size: 0.7rem; font-weight: 600; white-space: nowrap;">⚠ 不整合</span>` : ''}
      </div>`;
    }).join("");
  }

  // ===== 2. 初期データ読み込み & 描画 =====
  async function loadAndRender() {
    try {
      allContractHistory = await window.aivicApi.list(contractHistoryIdx) || allContractHistory;
      allBilling = await window.aivicApi.list(billingIdx) || allBilling;
      allContracts = await window.aivicApi.list(contractIdx) || allContracts;
      allCustomers = await window.aivicApi.list(customerIdx) || allCustomers;
    } catch (e) {
      console.warn("API load error:", e);
    }
    renderContractHistory(allContractHistory);
    renderBillingHistory(allBilling);
    renderTimeline(allContractHistory, allBilling);
  }
  loadAndRender();

  // ===== 3. 検索ボタン =====
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const contractId = container.querySelector("#filter-contract-id").value.trim().toLowerCase();
    const customerName = container.querySelector("#filter-customer-name").value.trim().toLowerCase();
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;

    let filteredContracts = allContracts;
    if (contractId) {
      filteredContracts = filteredContracts.filter(c => (c.契約ID || "").toLowerCase().includes(contractId));
    }
    if (customerName) {
      const matchingCustomerIds = allCustomers
        .filter(cust => (cust.顧客名 || "").toLowerCase().includes(customerName))
        .map(cust => cust.顧客ID);
      filteredContracts = filteredContracts.filter(c => matchingCustomerIds.includes(c.顧客企業ID));
    }

    const contractIds = filteredContracts.map(c => c.契約ID);

    let filteredHistory = allContractHistory.filter(h => contractIds.includes(h.契約ID));
    let filteredBilling = allBilling.filter(b => contractIds.includes(b.契約ID));

    if (startDate) {
      const start = new Date(startDate);
      filteredHistory = filteredHistory.filter(h => new Date(h.作成日時) >= start);
      filteredBilling = filteredBilling.filter(b => new Date(b.請求日) >= start);
    }
    if (endDate) {
      const end = new Date(endDate);
      end.setHours(23, 59, 59, 999);
      filteredHistory = filteredHistory.filter(h => new Date(h.作成日時) <= end);
      filteredBilling = filteredBilling.filter(b => new Date(b.請求日) <= end);
    }

    renderContractHistory(filteredHistory);
    renderBillingHistory(filteredBilling);
    renderTimeline(filteredHistory, filteredBilling);
  });

  // ===== 4. ダッシュボード遷移 =====
  container.querySelector("[data-testid='back-to-dashboard']").addEventListener("click", () => {
    window.showScreen("scr-1781943762164");
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0=請求, 1=請求明細, 2=契約, 3=顧客
  const invoiceTableIndex = 0;
  const detailTableIndex = 1;
  const contractTableIndex = 2;
  const customerTableIndex = 3;

  let currentInvoice = null;
  let currentDetails = [];
  let confirmAction = null;

  // ========== ユーティリティ関数 ==========
  function formatCurrency(amount) {
    return '¥' + (amount || 0).toLocaleString('ja-JP');
  }

  function formatDate(dateStr) {
    if (!dateStr) return '-';
    try {
      const d = new Date(dateStr);
      return d.toLocaleDateString('ja-JP');
    } catch {
      return dateStr;
    }
  }

  function showError(message) {
    const banner = container.querySelector('#error-banner');
    banner.querySelector('[data-testid="error-message"]').textContent = message;
    banner.removeAttribute('hidden');
    setTimeout(() => banner.setAttribute('hidden', ''), 5000);
  }

  function showSuccess(message) {
    const banner = container.querySelector('#success-banner');
    banner.querySelector('[data-testid="success-message"]').textContent = message;
    banner.removeAttribute('hidden');
    setTimeout(() => banner.setAttribute('hidden', ''), 3000);
  }

  function showConfirmModal(title, message, onConfirm) {
    const modal = container.querySelector('#confirm-modal');
    modal.querySelector('[data-testid="modal-title"]').textContent = title;
    modal.querySelector('[data-testid="modal-message"]').textContent = message;
    confirmAction = onConfirm;
    modal.removeAttribute('hidden');
  }

  function closeConfirmModal() {
    const modal = container.querySelector('#confirm-modal');
    modal.setAttribute('hidden', '');
    confirmAction = null;
  }

  // ========== 明細テーブル再描画 ==========
  function renderDetailRows(details) {
    const tbody = container.querySelector('#invoice-details-tbody');
    if (!details || details.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="padding: 2rem; text-align: center; color: var(--text-muted);">明細がありません</td></tr>';
      return;
    }

    tbody.innerHTML = details.map(detail => {
      const statusColor = detail.検証ステータス === '検証済み' ? '#51cf66' : detail.検証ステータス === '差異検出' ? '#ff922b' : '#9fb0d1';
      const statusLabel = detail.検証ステータス || '未検証';

      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 0.5rem; color: var(--text); font-size: 0.8rem;">${detail.明細種別 || '-'}</td>
          <td style="padding: 0.5rem; color: var(--text); font-size: 0.8rem; max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${detail.説明 || ''}">${detail.説明 || '-'}</td>
          <td style="padding: 0.5rem; text-align: right; color: var(--text); font-size: 0.8rem;">${detail.数量 || 0}</td>
          <td style="padding: 0.5rem; text-align: right; color: var(--text); font-size: 0.8rem;">${formatCurrency(detail.単価)}</td>
          <td style="padding: 0.5rem; text-align: right; color: var(--text); font-weight: 500; font-size: 0.8rem;">${formatCurrency(detail.金額)}</td>
          <td style="padding: 0.5rem; text-align: right; color: var(--text); font-size: 0.8rem;">${detail.税率 || 0}%</td>
          <td style="padding: 0.5rem; text-align: right; color: var(--text); font-weight: 500; font-size: 0.8rem;">${formatCurrency(detail.税額)}</td>
          <td style="padding: 0.5rem; text-align: center;">
            <span style="display: inline-block; width: 0.5rem; height: 0.5rem; border-radius: 50%; background: ${statusColor}; title='${statusLabel}'"></span>
          </td>
        </tr>
      `;
    }).join('');
  }

  // ========== 請求情報表示 ==========
  function displayInvoice(invoice) {
    currentInvoice = invoice;

    container.querySelector('[data-testid="invoice-id"]').textContent = invoice.請求ID?.substring(0, 8) || '-';
    container.querySelector('[data-testid="invoice-month"]').textContent = invoice.請求年月 || '-';
    container.querySelector('[data-testid="customer-name"]').textContent = invoice.顧客名 || '-';
    container.querySelector('[data-testid="contract-id"]').textContent = invoice.契約ID?.substring(0, 8) || '-';
    container.querySelector('[data-testid="invoice-date"]').textContent = formatDate(invoice.請求日);
    container.querySelector('[data-testid="due-date"]').textContent = formatDate(invoice.支払期限日);

    // 金額計算
    const subtotal = currentDetails.reduce((sum, d) => sum + (d.金額 || 0), 0);
    const taxAmount = currentDetails.reduce((sum, d) => sum + (d.税額 || 0), 0);
    const total = subtotal + taxAmount;

    container.querySelector('[data-testid="subtotal"]').textContent = formatCurrency(subtotal);
    container.querySelector('[data-testid="tax-amount"]').textContent = formatCurrency(taxAmount);
    container.querySelector('[data-testid="total-amount"]').textContent = formatCurrency(total);

    // 検証ステータス
    const detailStatuses = currentDetails.map(d => d.検証ステータス);
    const hasError = detailStatuses.includes('差異検出');
    const allVerified = detailStatuses.every(s => s === '検証済み');

    let statusHtml = '';
    if (hasError) {
      statusHtml = '<div style="display: flex; align-items: center; gap: 0.5rem; color: #ff922b;"><span style="display: inline-block; width: 0.5rem; height: 0.5rem; border-radius: 50%; background: #ff922b;"></span><span>差異が検出されています</span></div>';
    } else if (allVerified) {
      statusHtml = '<div style="display: flex; align-items: center; gap: 0.5rem; color: #51cf66;"><span style="display: inline-block; width: 0.5rem; height: 0.5rem; border-radius: 50%; background: #51cf66;"></span><span>全明細検証済み</span></div>';
    } else {
      statusHtml = '<div style="display: flex; align-items: center; gap: 0.5rem; color: #9fb0d1;"><span style="display: inline-block; width: 0.5rem; height: 0.5rem; border-radius: 50%; background: #9fb0d1;"></span><span>検証中...</span></div>';
    }
    container.querySelector('[data-testid="validation-status"]').innerHTML = statusHtml;
  }

  // ========== 初期化：URL パラメータから請求ID取得 ==========
  async function init() {
    try {
      // URL パラメータから請求ID取得（例: ?invoiceId=xxx）
      const params = new URLSearchParams(window.location.search);
      const invoiceId = params.get('invoiceId');

      if (!invoiceId) {
        showError('請求IDが指定されていません');
        return;
      }

      // 請求データ取得
      const invoices = await window.aivicApi.list(invoiceTableIndex);
      const invoice = invoices?.find(i => i.請求ID === invoiceId);

      if (!invoice) {
        showError('請求データが見つかりません');
        return;
      }

      // 請求明細取得
      const details = await window.aivicApi.list(detailTableIndex);
      currentDetails = details?.filter(d => d.請求ID === invoiceId) || [];

      displayInvoice(invoice);
      renderDetailRows(currentDetails);

    } catch (err) {
      console.error('初期化エラー:', err);
      showError('データ読み込みエラーが発生しました');
    }
  }

  // ========== ボタンイベント ==========

  // 戻るボタン
  container.querySelector('[data-testid="back-button"]').addEventListener('click', () => {
    window.showScreen('scr-1781943924387'); // 請求検証管理画面へ
  });

  // 却下ボタン
  container.querySelector('[data-testid="reject-button"]').addEventListener('click', () => {
    const status = container.querySelector('[data-testid="approval-status"]').value;
    const comment = container.querySelector('[data-testid="approval-comment"]').value;

    if (!status) {
      showError('判定を選択してください');
      return;
    }

    showConfirmModal(
      '請求却下の確認',
      `この請求を却下します。理由: ${comment || '(未記入)'}`,
      async () => {
        try {
          await window.aivicApi.update(invoiceTableIndex, currentInvoice.請求ID, {
            請求ステータス: 'キャンセル',
            摘要: comment
          });
          showSuccess('請求を却下しました');
          setTimeout(() => window.showScreen('scr-1781943924387'), 1500);
        } catch (err) {
          showError('却下処理に失敗しました');
        }
        closeConfirmModal();
      }
    );
  });

  // 承認・確定ボタン
  container.querySelector('[data-testid="approve-button"]').addEventListener('click', () => {
    const status = container.querySelector('[data-testid="approval-status"]').value;
    const comment = container.querySelector('[data-testid="approval-comment"]').value;
    const confirmed = container.querySelector('[data-testid="confirm-checkbox"]').checked;

    if (!status) {
      showError('判定を選択してください');
      return;
    }

    if (!confirmed) {
      showError('確認チェックボックスをチェックしてください');
      return;
    }

    const actionLabel = status === 'approved' ? '承認・確定' : status === 'rejected' ? '却下' : '保留';

    showConfirmModal(
      `請求${actionLabel}の確認`,
      `この請求を${actionLabel}します。理由: ${comment || '(未記入)'}`,
      async () => {
        try {
          const newStatus = status === 'approved' ? '請求済' : status === 'rejected' ? 'キャンセル' : '保留中';

          await window.aivicApi.update(invoiceTableIndex, currentInvoice.請求ID, {
            請求ステータス: newStatus,
            摘要: comment
          });

          // 操作ログ記録（オプション）
          showSuccess(`請求を${actionLabel}しました`);
          setTimeout(() => window.showScreen('scr-1781943924387'), 1500);
        } catch (err) {
          showError(`${actionLabel}処理に失敗しました`);
        }
        closeConfirmModal();
      }
    );
  });

  // 確認モーダルのボタン
  container.querySelector('[data-testid="modal-confirm"]').addEventListener('click', () => {
    if (confirmAction) confirmAction();
  });

  container.querySelector('[data-testid="modal-cancel"]').addEventListener('click', closeConfirmModal);

  // ========== 初期化実行 ==========
  init();
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 契約履歴=0, 請求=1, 顧客=2
  const contractHistoryTable = tables[0];
  const billingTable = tables[1];
  const customerTable = tables[2];

  // 顧客マップを作成（顧客IDから顧客名を取得）
  const customerMap = {};
  if (customerTable && customerTable.records) {
    customerTable.records.forEach(c => {
      customerMap[c.id] = c.顧客名 || c.customer_name || '';
    });
  }

  // ============ 契約履歴テーブル再描画 ============
  function renderContractHistory(rows) {
    const tbody = container.querySelector('#contract-history-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: var(--bg-card); color: var(--text-muted);"><td colspan="6" style="padding: 16px; text-align: center;">該当するデータがありません</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(row => {
      const contractId = row.contract_id || row.contractId || row.id || '';
      const customerId = row.customer_id || row.customerId || '';
      const customerName = customerMap[customerId] || '—';
      const changeType = row.change_type || row.変更種別 || '—';
      const changeField = row.change_field || row.変更フィールド名 || '—';
      const verificationStatus = row.verification_status || row.請求検証ステータス || '—';
      const createdAt = row.created_at || row.作成日時 || '—';
      const displayDate = createdAt ? new Date(createdAt).toLocaleDateString('ja-JP') : '—';

      return `<tr style="background: var(--bg-card); border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer;" data-id="${row.id}" class="contract-history-row">
        <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.05); color: var(--text);">${contractId.substring(0, 8)}</td>
        <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.05); color: var(--text);">${customerName}</td>
        <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.05); color: var(--text);">${changeType}</td>
        <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.05); color: var(--text-muted); font-size: 12px;">${changeField}</td>
        <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.05); color: var(--text);">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 11px; background: ${verificationStatus === '検証済み' ? 'rgba(76,175,80,0.2)' : verificationStatus === '不一致' ? 'rgba(244,67,54,0.2)' : 'rgba(158,158,158,0.2)'}; color: ${verificationStatus === '検証済み' ? '#4caf50' : verificationStatus === '不一致' ? '#f44336' : 'var(--text-muted)'};">${verificationStatus}</span>
        </td>
        <td style="padding: 8px; color: var(--text-muted); font-size: 12px;">${displayDate}</td>
      </tr>`;
    }).join('');
  }

  // ============ 請求テーブル再描画 ============
  function renderBilling(rows) {
    const tbody = container.querySelector('#billing-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: var(--bg-card); color: var(--text-muted);"><td colspan="6" style="padding: 16px; text-align: center;">該当するデータがありません</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(row => {
      const billingId = row.billing_id || row.請求ID || row.id || '';
      const contractId = row.contract_id || row.contractId || '—';
      const billingMonth = row.billing_month || row.請求年月 || '—';
      const amount = row.billing_amount || row.請求金額 || 0;
      const status = row.billing_status || row.請求ステータス || '—';
      const billingDate = row.billing_date || row.請求日 || '—';
      const displayDate = billingDate ? new Date(billingDate).toLocaleDateString('ja-JP') : '—';

      const statusColor = status === '支払済' ? 'rgba(76,175,80,0.2)' : status === '延滞' ? 'rgba(244,67,54,0.2)' : status === '請求済' ? 'rgba(33,150,243,0.2)' : 'rgba(158,158,158,0.2)';
      const statusTextColor = status === '支払済' ? '#4caf50' : status === '延滞' ? '#f44336' : status === '請求済' ? '#2196f3' : 'var(--text-muted)';

      return `<tr style="background: var(--bg-card); border-bottom: 1px solid rgba(255,255,255,0.05);" data-id="${row.id}">
        <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.05); color: var(--text);">${billingId.substring(0, 8)}</td>
        <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.05); color: var(--text);">${contractId.substring(0, 8)}</td>
        <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.05); color: var(--text);">${billingMonth}</td>
        <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.05); color: var(--text); text-align: right;">${amount.toLocaleString('ja-JP')}円</td>
        <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.05);">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 11px; background: ${statusColor}; color: ${statusTextColor};">${status}</span>
        </td>
        <td style="padding: 8px; color: var(--text-muted); font-size: 12px;">${displayDate}</td>
      </tr>`;
    }).join('');
  }

  // ============ 初期データ描画 ============
  if (contractHistoryTable && contractHistoryTable.records) {
    renderContractHistory(contractHistoryTable.records);
  }
  if (billingTable && billingTable.records) {
    renderBilling(billingTable.records);
  }

  // ============ 契約履歴検索 ============
  container.querySelector('#btn-search-contract').addEventListener('click', async () => {
    const customerName = container.querySelector('#search-customer-name').value.trim();
    const customerId = container.querySelector('#search-customer-id').value.trim();
    const contractId = container.querySelector('#search-contract-id').value.trim();
    const contractStatus = container.querySelector('#search-contract-status').value;
    const startDateFrom = container.querySelector('#search-start-date-from').value;
    const startDateTo = container.querySelector('#search-start-date-to').value;
    const endDateFrom = container.querySelector('#search-end-date-from').value;
    const endDateTo = container.querySelector('#search-end-date-to').value;

    const rows = await window.aivicApi.list(0) || contractHistoryTable.records || [];

    const filtered = rows.filter(row => {
      const rowCustomerId = row.customer_id || row.customerId || '';
      const rowContractId = row.contract_id || row.contractId || row.id || '';
      const rowStatus = row.contract_status || row.契約ステータス || '';
      const rowStartDate = row.contract_start_date || row.契約開始日 || '';
      const rowEndDate = row.contract_end_date || row.契約終了日 || '';
      const rowCustomerName = customerMap[rowCustomerId] || '';

      if (customerName && !rowCustomerName.includes(customerName)) return false;
      if (customerId && !rowCustomerId.includes(customerId)) return false;
      if (contractId && !rowContractId.includes(contractId)) return false;
      if (contractStatus && rowStatus !== contractStatus) return false;
      if (startDateFrom && new Date(rowStartDate) < new Date(startDateFrom)) return false;
      if (startDateTo && new Date(rowStartDate) > new Date(startDateTo)) return false;
      if (endDateFrom && new Date(rowEndDate) < new Date(endDateFrom)) return false;
      if (endDateTo && new Date(rowEndDate) > new Date(endDateTo)) return false;
      return true;
    });

    renderContractHistory(filtered);
  });

  // ============ 契約履歴リセット ============
  container.querySelector('#btn-reset-contract').addEventListener('click', () => {
    container.querySelector('#search-customer-name').value = '';
    container.querySelector('#search-customer-id').value = '';
    container.querySelector('#search-contract-id').value = '';
    container.querySelector('#search-contract-status').value = '';
    container.querySelector('#search-start-date-from').value = '';
    container.querySelector('#search-start-date-to').value = '';
    container.querySelector('#search-end-date-from').value = '';
    container.querySelector('#search-end-date-to').value = '';
    renderContractHistory(contractHistoryTable.records || []);
  });

  // ============ 請求検索 ============
  container.querySelector('#btn-search-billing').addEventListener('click', async () => {
    const billingMonth = container.querySelector('#search-billing-month').value;
    const billingStatus = container.querySelector('#search-billing-status').value;
    const billingDateFrom = container.querySelector('#search-billing-date-from').value;
    const billingDateTo = container.querySelector('#search-billing-date-to').value;
    const amountFrom = parseInt(container.querySelector('#search-amount-from').value) || 0;
    const amountTo = parseInt(container.querySelector('#search-amount-to').value) || Infinity;

    const rows = await window.aivicApi.list(1) || billingTable.records || [];

    const filtered = rows.filter(row => {
      const rowMonth = row.billing_month || row.請求年月 || '';
      const rowStatus = row.billing_status || row.請求ステータス || '';
      const rowDate = row.billing_date || row.請求日 || '';
      const rowAmount = row.billing_amount || row.請求金額 || 0;

      if (billingMonth && !rowMonth.includes(billingMonth)) return false;
      if (billingStatus && rowStatus !== billingStatus) return false;
      if (billingDateFrom && new Date(rowDate) < new Date(billingDateFrom)) return false;
      if (billingDateTo && new Date(rowDate) > new Date(billingDateTo)) return false;
      if (rowAmount < amountFrom || rowAmount > amountTo) return false;
      return true;
    });

    renderBilling(filtered);
  });

  // ============ 請求リセット ============
  container.querySelector('#btn-reset-billing').addEventListener('click', () => {
    container.querySelector('#search-billing-month').value = '';
    container.querySelector('#search-billing-status').value = '';
    container.querySelector('#search-billing-date-from').value = '';
    container.querySelector('#search-billing-date-to').value = '';
    container.querySelector('#search-amount-from').value = '';
    container.querySelector('#search-amount-to').value = '';
    renderBilling(billingTable.records || []);
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（仮定）
  const contractTableIdx = 0;
  const billingTableIdx = 1;
  const billingDetailTableIdx = 2;
  const verificationTableIdx = 3;

  // 初期データ
  const contractsData = tables[contractTableIdx]?.records || [];
  const billingsData = tables[billingTableIdx]?.records || [];
  const billingDetailsData = tables[billingDetailTableIdx]?.records || [];
  const verificationsData = tables[verificationTableIdx]?.records || [];

  // 現在の検証対象
  let currentContractId = null;
  let currentBillingId = null;
  let currentVerification = null;

  // ===== 1. 検証データ読み込み処理 =====
  function loadVerificationData() {
    const contractId = container.querySelector("#contract-select").value;
    const billingId = container.querySelector("#billing-select").value;

    if (!contractId || !billingId) {
      alert("契約と請求を選択してください");
      return;
    }

    currentContractId = contractId;
    currentBillingId = billingId;

    // 契約情報を表示
    const contract = contractsData.find(c => c.id === contractId || c.契約ID === contractId);
    if (contract) {
      container.querySelector("#contract-id-display").textContent = contract.id || contract.契約ID || "-";
      container.querySelector("#contract-name-display").textContent = contract.契約名 || "-";
      container.querySelector("#contract-amount-display").textContent = 
        contract.契約金額 ? `¥${contract.契約金額.toLocaleString()}` : "-";
      container.querySelector("#contract-period-display").textContent = 
        `${contract.契約開始日 || "-"} ～ ${contract.契約終了日 || "-"}`;
      container.querySelector("#contract-status-display").textContent = contract.契約ステータス || "-";
    }

    // 請求明細を表示
    const billingDetails = billingDetailsData.filter(bd => bd.請求ID === billingId || bd.id?.includes(billingId));
    renderBillingDetails(billingDetails);

    // 検証ステータスを初期化
    container.querySelector("#status-display").textContent = "未検証";
    container.querySelector("#verifier-display").textContent = "-";
    container.querySelector("#verification-date-display").textContent = "-";
    container.querySelector("#verification-result").value = "";
    container.querySelector("#verification-comment").value = "";
  }

  // ===== 2. 請求明細テーブル再描画 =====
  function renderBillingDetails(details) {
    const tbody = container.querySelector("#billing-tbody");
    if (details.length === 0) {
      tbody.innerHTML = `<tr style="border-bottom: 1px solid rgba(255,255,255,0.05);"><td colspan="4" style="padding: 6px 4px; text-align: center; color: var(--text-muted);">明細がありません</td></tr>`;
      container.querySelector("#billing-total-display").textContent = "¥0";
      container.querySelector("#billing-status-display").textContent = "-";
      return;
    }

    let totalAmount = 0;
    tbody.innerHTML = details.map(detail => {
      const amount = (detail.数量 || 0) * (detail.単価 || 0);
      totalAmount += amount;
      return `<tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
        <td style="padding: 6px 4px; color: var(--text);">${detail.明細種別 || "-"}</td>
        <td style="text-align: right; padding: 6px 4px; color: var(--text);">${detail.数量 || 0}</td>
        <td style="text-align: right; padding: 6px 4px; color: var(--text);">¥${(detail.単価 || 0).toLocaleString()}</td>
        <td style="text-align: right; padding: 6px 4px; color: var(--text); font-weight: 600;">¥${amount.toLocaleString()}</td>
      </tr>`;
    }).join("");

    container.querySelector("#billing-total-display").textContent = `¥${totalAmount.toLocaleString()}`;
    container.querySelector("#billing-status-display").textContent = details[0]?.検証ステータス || "未検証";
  }

  // ===== 3. 検証履歴表示 =====
  function renderVerificationHistory() {
    const historyDiv = container.querySelector("#verification-history");
    const history = verificationsData.filter(v => v.契約ID === currentContractId && v.請求ID === currentBillingId);

    if (history.length === 0) {
      historyDiv.innerHTML = `<div style="padding: 6px; background: rgba(0,0,0,0.15); border-radius: 4px; color: var(--text-muted);">履歴がありません</div>`;
      return;
    }

    historyDiv.innerHTML = history.map(h => `
      <div style="padding: 6px; background: rgba(0,0,0,0.15); border-radius: 4px; border-left: 3px solid ${
        h.検証結果 === "承認" ? "#4CAF50" : h.検証結果 === "却下" ? "#f44336" : "#ff9800"
      };">
        <div style="font-weight: 600; color: var(--text);">${h.検証結果 || "-"}</div>
        <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">${h.検証者名 || "-"} / ${h.検証日時 || "-"}</div>
        ${h.検証コメント ? `<div style="font-size: 10px; color: var(--text); margin-top: 2px;">${h.検証コメント}</div>` : ""}
      </div>
    `).join("");
  }

  // ===== 4. 承認・却下・保留処理 =====
  async function submitVerification(result) {
    const comment = container.querySelector("#verification-comment").value;

    if (!currentContractId || !currentBillingId) {
      alert("検証対象を選択してください");
      return;
    }

    const verificationData = {
      契約ID: currentContractId,
      請求ID: currentBillingId,
      検証結果: result,
      検証コメント: comment,
      検証者名: "現在のユーザー", // 実際にはセッション情報から取得
      検証日時: new Date().toLocaleString("ja-JP"),
      ステータス: result === "承認" ? "承認済み" : result === "却下" ? "却下" : "保留中"
    };

    // API保存（失敗時は自動通知）
    const saved = await window.aivicApi.save(verificationTableIdx, verificationData);
    if (saved) {
      // ステータス更新
      container.querySelector("#status-display").textContent = verificationData.ステータス;
      container.querySelector("#verifier-display").textContent = verificationData.検証者名;
      container.querySelector("#verification-date-display").textContent = verificationData.検証日時;

      // 履歴更新
      renderVerificationHistory();

      // フォームリセット
      container.querySelector("#verification-result").value = "";
      container.querySelector("#verification-comment").value = "";

      alert(`検証結果を${result}として記録しました`);
    }
  }

  // ===== 5. イベントリスナー登録 =====
  container.querySelector("#btn-load-verification").addEventListener("click", loadVerificationData);

  container.querySelector("#btn-approve").addEventListener("click", () => submitVerification("承認"));
  container.querySelector("#btn-reject").addEventListener("click", () => submitVerification("却下"));
  container.querySelector("#btn-pending").addEventListener("click", () => submitVerification("保留"));

  // 初期表示
  renderBillingDetails([]);
  renderVerificationHistory();
}

function(container, apiUrl, tables) {
