function(container, apiUrl, tables) {
  const contractTable = tables[0];
  const contractTbody = container.querySelector("#contract-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const noSelection = container.querySelector("#no-selection");
  const detailHeader = container.querySelector("#detail-header");
  const uploadModal = container.querySelector("#upload-modal");
  const dropZone = container.querySelector("#drop-zone");
  const fileInput = container.querySelector("#file-input");
  const verifyResult = container.querySelector("#verify-result");
  const errorList = container.querySelector("#error-list");

  let selectedContractId = null;
  let selectedContractData = null;

  // 1. 契約一覧の再描画
  function renderContractList(rows) {
    contractTbody.innerHTML = rows.map(r => {
      const statusColor = {
        '提案中': '#ff9800',
        '承認待ち': '#2196f3',
        '契約済': '#4caf50',
        '完了': '#9c27b0',
        '終了': '#757575'
      }[r.契約ステータス] || '#9fb0d1';

      return `
        <tr
          data-id="${r.契約ID}"
          class="contract-row"
          style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.08);"
        >
          <td style="padding: 8px; color: var(--text); font-size: 12px;">${r.契約名 || ''}</td>
          <td style="padding: 8px; text-align: center;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${statusColor}20; color: ${statusColor}; font-size: 11px; font-weight: 500;">
              ${r.契約ステータス || ''}
            </span>
          </td>
          <td style="padding: 8px; text-align: right; color: var(--text); font-size: 12px; font-weight: 500;">
            ¥${(r.契約金額 || 0).toLocaleString()}
          </td>
        </tr>
      `;
    }).join('');

    if (rows.length === 0) {
      contractTbody.innerHTML = '<tr style="opacity: 0.6;"><td colspan="3" style="padding: 12px; text-align: center; color: var(--text-muted);">該当する契約がありません</td></tr>';
    }
  }

  // 2. 詳細パネルの表示
  function showDetail(contractData) {
    selectedContractId = contractData.契約ID;
    selectedContractData = contractData;

    container.querySelector("#detail-id").textContent = contractData.契約ID || '';
    container.querySelector("#detail-customer").textContent = contractData.顧客企業ID || '（未設定）';
    container.querySelector("#detail-start-date").textContent = contractData.契約開始日 ? new Date(contractData.契約開始日).toLocaleDateString('ja-JP') : '';
    container.querySelector("#detail-end-date").textContent = contractData.契約終了日 ? new Date(contractData.契約終了日).toLocaleDateString('ja-JP') : '';
    container.querySelector("#detail-amount").textContent = `¥${(contractData.契約金額 || 0).toLocaleString()}`;
    container.querySelector("#detail-content").textContent = contractData.契約内容 || '（記載なし）';

    noSelection.style.display = 'none';
    detailPanel.style.display = 'flex';
    verifyResult.style.display = 'none';
    errorList.style.display = 'none';

    // チェックボックスをリセット
    container.querySelector("#check-amount").checked = false;
    container.querySelector("#check-dates").checked = false;
    container.querySelector("#check-billing").checked = false;
    container.querySelector("#check-history").checked = false;
  }

  // 3. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    renderContractList(rows || contractTable.records || []);
  });

  // 4. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const nameKeyword = container.querySelector('[data-testid="contract-name-search"]').value.toLowerCase();
    const statusFilter = container.querySelector('[data-testid="status-filter"]').value;

    const rows = await window.aivicApi.list(0) || contractTable.records || [];
    const filtered = rows.filter(r => {
      const nameMatch = !nameKeyword || (r.契約名 || '').toLowerCase().includes(nameKeyword);
      const statusMatch = !statusFilter || r.契約ステータス === statusFilter;
      return nameMatch && statusMatch;
    });

    renderContractList(filtered);
  });

  // 5. 契約行クリック（詳細表示）
  container.addEventListener("click", e => {
    const row = e.target.closest(".contract-row");
    if (row) {
      const contractId = row.dataset.id;
      window.aivicApi.list(0).then(rows => {
        const contract = (rows || contractTable.records || []).find(r => r.契約ID === contractId);
        if (contract) showDetail(contract);
      });
    }
  });

  // 6. 検証実行ボタン
  container.querySelector("#btn-verify").addEventListener("click", () => {
    if (!selectedContractData) return;

    const checks = {
      amount: container.querySelector("#check-amount").checked,
      dates: container.querySelector("#check-dates").checked,
      billing: container.querySelector("#check-billing").checked,
      history: container.querySelector("#check-history").checked
    };

    const results = [];
    const errors = [];

    if (checks.amount) {
      if (selectedContractData.契約金額 > 0) {
        results.push("✓ 契約金額: 有効");
      } else {
        errors.push("契約金額が0円または未設定です");
      }
    }

    if (checks.dates) {
      const start = new Date(selectedContractData.契約開始日);
      const end = new Date(selectedContractData.契約終了日);
      if (start < end) {
        results.push("✓ 契約期間: 有効");
      } else {
        errors.push("契約終了日が開始日より前です");
      }
    }

    if (checks.billing) {
      results.push("✓ 請求照合: 準備完了（詳細は請求照合画面で確認）");
    }

    if (checks.history) {
      results.push("✓ 変更履歴: 記録あり");
    }

    if (results.length === 0 && errors.length === 0) {
      results.push("検証項目を選択してください");
    }

    // 結果表示
    const resultStatus = container.querySelector("#result-status");
    resultStatus.textContent = errors.length === 0 ? "✓ 検証完了: 問題なし" : "⚠ 検証完了: 警告あり";
    resultStatus.style.background = errors.length === 0 ? "rgba(76, 175, 80, 0.15)" : "rgba(255, 152, 0, 0.15)";
    resultStatus.style.color = errors.length === 0 ? "#4caf50" : "#ff9800";

    container.querySelector("#result-details").innerHTML = results.map(r => `<div>${r}</div>`).join('');

    if (errors.length > 0) {
      container.querySelector("#error-items").innerHTML = errors.map(e => `<li>${e}</li>`).join('');
      errorList.style.display = 'block';
    } else {
      errorList.style.display = 'none';
    }

    verifyResult.style.display = 'block';
  });

  // 7. 請求照合ボタン
  container.querySelector("#btn-reconcile").addEventListener("click", () => {
    if (selectedContractId) {
      window.showScreen("scr-1781943977121");
    }
  });

  // 8. 変更履歴ボタン
  container.querySelector("#btn-history").addEventListener("click", () => {
    window.showScreen("scr-1781943896586");
  });

  // 9. 編集ボタン
  container.querySelector("#btn-edit").addEventListener("click", () => {
    window.showScreen("scr-1781943871827");
  });

  // 10. ファイルアップロード機能
  const btnSelectFile = container.querySelector("#btn-select-file");
  const btnCancelUpload = container.querySelector("#btn-cancel-upload");
  const btnUpload = container.querySelector("#btn-upload");
  const fileInfo = container.querySelector("#file-info");
  const previewArea = container.querySelector("#preview-area");

  btnSelectFile.addEventListener("click", () => {
    fileInput.click();
  });

  dropZone.addEventListener("dragover", e => {
    e.preventDefault();
    dropZone.style.borderColor = "var(--primary)";
    dropZone.style.background = "rgba(255,255,255,0.05)";
  });

  dropZone.addEventListener("dragleave", () => {
    dropZone.style.borderColor = "rgba(255,255,255,0.3)";
    dropZone.style.background = "transparent";
  });

  dropZone.addEventListener("drop", e => {
    e.preventDefault();
    dropZone.style.borderColor = "rgba(255,255,255,0.3)";
    dropZone.style.background = "transparent";
    if (e.dataTransfer.files.length > 0) {
      handleFileSelect(e.dataTransfer.files[0]);
    }
  });

  fileInput.addEventListener("change", e => {
    if (e.target.files.length > 0) {
      handleFileSelect(e.target.files[0]);
    }
  });

  function handleFileSelect(file) {
    container.querySelector("#file-name").textContent = file.name;
    container.querySelector("#file-size").textContent = (file.size / 1024).toFixed(2) + " KB";
    fileInfo.style.display = 'block';

    const reader = new FileReader();
    reader.onload = e => {
      const text = e.target.result;
      const preview = text.substring(0, 500);
      container.querySelector("#preview-content").textContent = preview + (text.length > 500 ? "\n... (以降省略)" : "");
      previewArea.style.display = 'block';
    };
    reader.readAsText(file);
  }

  btnCancelUpload.addEventListener("click", () => {
    uploadModal.style.display = 'none';
    fileInfo.style.display = 'none';
    previewArea.style.display = 'none';
    fileInput.value = '';
  });

  btnUpload.addEventListener("click", async () => {
    if (!selectedContractId || !fileInput.files.length) {
      alert("契約を選択し、ファイルを指定してください");
      return;
    }

    const file = fileInput.files[0];
    const formData = new FormData();
    formData.append("contractId", selectedContractId);
    formData.append("file", file);

    try {
      const response = await fetch(apiUrl + "/api/contracts/upload", {
        method: "POST",
        body: formData
      });
      if (response.ok) {
        alert("ファイルをアップロードしました");
        uploadModal.style.display = 'none';
        fileInfo.style.display = 'none';
        previewArea.style.display = 'none';
        fileInput.value = '';
      }
    } catch (err) {
      console.error("Upload error:", err);
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0=請求, 1=請求明細, 2=契約, 3=顧客
  const invoiceTableIndex = 0;
  const invoiceDetailTableIndex = 1;
  const contractTableIndex = 2;
  const customerTableIndex = 3;

  let allVerifications = [];
  let selectedVerification = null;

  // ===== 1. 検証結果の再描画関数 =====
  function renderVerifications(verifications) {
    const tbody = container.querySelector("#verification-tbody");
    const count = container.querySelector("#result-count");
    count.textContent = verifications.length;

    if (verifications.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);"><td colspan="7" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 12px;">検証結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = verifications.map(v => {
      const diffAmount = v.invoiceAmount - v.contractAmount;
      const diffPercent = v.contractAmount > 0 ? ((diffAmount / v.contractAmount) * 100).toFixed(1) : 0;
      const hasMismatch = v.hasMismatch ? '⚠ あり' : '✓ なし';
      const mismatchColor = v.hasMismatch ? 'color: #ff6464;' : 'color: #64ff96;';
      const statusBg = v.verificationStatus === '検証済み' ? 'background: rgba(100,255,150,0.2);' : 
                       v.verificationStatus === '差異検出' ? 'background: rgba(255,100,100,0.2);' : 
                       'background: rgba(100,150,200,0.2);';

      return `
        <tr data-id="${v.id}" class="verification-row" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background=''">
          <td style="padding: 8px; color: var(--text);">${v.contractId || '-'}</td>
          <td style="padding: 8px; color: var(--text);">${v.customerName || '-'}</td>
          <td style="padding: 8px; text-align: right; color: var(--text);">¥${(v.contractAmount || 0).toLocaleString()}</td>
          <td style="padding: 8px; text-align: right; color: var(--text);">¥${(v.invoiceAmount || 0).toLocaleString()}</td>
          <td style="padding: 8px; text-align: center; ${mismatchColor}">¥${diffAmount.toLocaleString()} (${diffPercent}%)</td>
          <td style="padding: 8px; text-align: center;"><span style="padding: 2px 6px; border-radius: 3px; font-size: 11px; ${statusBg}">${v.verificationStatus || '未検証'}</span></td>
          <td style="padding: 8px; text-align: center;"><button class="action-btn secondary detail-btn" data-id="${v.id}" style="padding: 4px 8px; font-size: 11px;">詳細</button></td>
        </tr>
      `;
    }).join('');
  }

  // ===== 2. 検証データの生成（契約 vs 請求の照合） =====
  async function generateVerifications() {
    const invoices = await window.aivicApi.list(invoiceTableIndex) || [];
    const contracts = await window.aivicApi.list(contractTableIndex) || [];
    const customers = await window.aivicApi.list(customerTableIndex) || [];
    const invoiceDetails = await window.aivicApi.list(invoiceDetailTableIndex) || [];

    const verifications = [];
    const contractMap = new Map(contracts.map(c => [c.id, c]));
    const customerMap = new Map(customers.map(c => [c.id, c]));

    invoices.forEach(inv => {
      const contract = contractMap.get(inv.contractId);
      const customer = customerMap.get(contract?.customerId);
      const details = invoiceDetails.filter(d => d.invoiceId === inv.id);

      const hasMismatch = inv.invoiceAmount !== contract?.contractAmount || 
                          details.some(d => d.verificationStatus === '差異検出');

      verifications.push({
        id: inv.id,
        contractId: contract?.contractId || inv.contractId,
        customerId: contract?.customerId,
        customerName: customer?.customerName || '-',
        contractAmount: contract?.contractAmount || 0,
        invoiceAmount: inv.invoiceAmount || 0,
        invoicePeriod: inv.invoiceYearMonth || '-',
        invoiceDate: inv.invoiceDate ? new Date(inv.invoiceDate).toLocaleDateString('ja-JP') : '-',
        invoiceDueDate: inv.paymentDueDate ? new Date(inv.paymentDueDate).toLocaleDateString('ja-JP') : '-',
        invoiceStatus: inv.invoiceStatus || '-',
        contractName: contract?.contractName || '-',
        contractStart: contract?.contractStartDate ? new Date(contract.contractStartDate).toLocaleDateString('ja-JP') : '-',
        contractEnd: contract?.contractEndDate ? new Date(contract.contractEndDate).toLocaleDateString('ja-JP') : '-',
        contractStatus: contract?.contractStatus || '-',
        hasMismatch: hasMismatch,
        verificationStatus: details.length > 0 ? details[0].verificationStatus : '未検証',
        details: details,
        contract: contract,
        invoice: inv
      });
    });

    return verifications;
  }

  // ===== 3. 詳細パネルの表示 =====
  function showDetailPanel(verification) {
    selectedVerification = verification;
    const panel = container.querySelector("#detail-panel");

    // 契約情報
    container.querySelector("#detail-contract-id").textContent = verification.contractId;
    container.querySelector("#detail-contract-name").textContent = verification.contractName;
    container.querySelector("#detail-contract-start").textContent = verification.contractStart;
    container.querySelector("#detail-contract-end").textContent = verification.contractEnd;
    container.querySelector("#detail-contract-amount").textContent = `¥${(verification.contractAmount || 0).toLocaleString()}`;
    container.querySelector("#detail-contract-status").textContent = verification.contractStatus;

    // 請求情報
    container.querySelector("#detail-invoice-period").textContent = verification.invoicePeriod;
    container.querySelector("#detail-invoice-date").textContent = verification.invoiceDate;
    container.querySelector("#detail-invoice-due").textContent = verification.invoiceDueDate;
    container.querySelector("#detail-invoice-amount").textContent = `¥${(verification.invoiceAmount || 0).toLocaleString()}`;
    container.querySelector("#detail-invoice-status").textContent = verification.invoiceStatus;

    // 不一致項目
    const mismatchSection = container.querySelector("#mismatch-section");
    const mismatchItems = container.querySelector("#mismatch-items");
    if (verification.hasMismatch) {
      const mismatches = [];
      if (verification.contractAmount !== verification.invoiceAmount) {
        mismatches.push(`<div>• 金額不一致: 契約 ¥${verification.contractAmount.toLocaleString()} → 請求 ¥${verification.invoiceAmount.toLocaleString()}</div>`);
      }
      verification.details.forEach(d => {
        if (d.verificationStatus === '差異検出') {
          mismatches.push(`<div>• 明細不一致 (${d.itemType}): ${d.discrepancyReason || '理由未記入'}</div>`);
        }
      });
      mismatchItems.innerHTML = mismatches.join('');
      mismatchSection.style.display = 'block';
    } else {
      mismatchSection.style.display = 'none';
    }

    // 差分詳細
    const diffSection = container.querySelector("#difference-section");
    const diffDetails = container.querySelector("#difference-details");
    const diffAmount = verification.invoiceAmount - verification.contractAmount;
    if (diffAmount !== 0) {
      diffDetails.innerHTML = `
        <div>• 差分金額: ¥${diffAmount.toLocaleString()} (${((diffAmount / verification.contractAmount) * 100).toFixed(1)}%)</div>
        <div>• 請求明細数: ${verification.details.length} 件</div>
        ${verification.details.map(d => `<div style="margin-top: 4px; padding-left: 12px; border-left: 2px solid rgba(100,200,255,0.3);">
          <strong>${d.itemType}:</strong> 数量 ${d.quantity} × 単価 ¥${d.unitPrice} = ¥${d.amount} (検証: ${d.verificationStatus})
        </div>`).join('')}
      `;
      diffSection.style.display = 'block';
    } else {
      diffSection.style.display = 'none';
    }

    // 修正提案
    const correctionSection = container.querySelector("#correction-section");
    const correctionProposal = container.querySelector("#correction-proposal");
    if (verification.hasMismatch) {
      correctionProposal.innerHTML = `
        <div>• 推奨アクション: ${diffAmount > 0 ? '請求金額を契約金額に修正' : '契約金額を請求金額に修正'}</div>
        <div>• 修正対象: ${verification.details.filter(d => d.verificationStatus === '差異検出').length} 件の明細</div>
      `;
      correctionSection.style.display = 'block';
    } else {
      correctionSection.style.display = 'none';
    }

    container.querySelector("#correction-reason").value = '';
    panel.style.display = 'block';
  }

  // ===== 4. 初期データ読み込み =====
  window.aivicApi.list(invoiceTableIndex).then(async () => {
    allVerifications = await generateVerifications();
    renderVerifications(allVerifications);
  });

  // ===== 5. 検索ボタン =====
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const period = container.querySelector("#filter-period").value;
    const contractId = container.querySelector("#filter-contract-id").value.toLowerCase();
    const customerName = container.querySelector("#filter-customer-name").value.toLowerCase();

    const filtered = allVerifications.filter(v => {
      const matchPeriod = !period || v.invoicePeriod.includes(period);
      const matchContract = !contractId || (v.contractId || '').toLowerCase().includes(contractId);
      const matchCustomer = !customerName || (v.customerName || '').toLowerCase().includes(customerName);
      return matchPeriod && matchContract && matchCustomer;
    });

    renderVerifications(filtered);
  });

  // ===== 6. リセットボタン =====
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#filter-period").value = '';
    container.querySelector("#filter-contract-id").value = '';
    container.querySelector("#filter-customer-name").value = '';
    renderVerifications(allVerifications);
  });

  // ===== 7. 詳細ボタン（イベントデリゲーション） =====
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const verification = allVerifications.find(v => v.id === id);
      if (verification) showDetailPanel(verification);
    }
  });

  // ===== 8. 修正承認ボタン =====
  container.querySelector("#btn-approve").addEventListener("click", async () => {
    if (!selectedVerification) return;
    const reason = container.querySelector("#correction-reason").value;
    if (!reason.trim()) {
      alert("修正理由を入力してください");
      return;
    }

    // 請求明細の検証ステータスを「検証済み」に更新
    for (const detail of selectedVerification.details) {
      await window.aivicApi.update(invoiceDetailTableIndex, detail.id, {
        verificationStatus: '検証済み',
        differenceReason: reason
      });
    }

    // 請求のステータスを「検証済み」に更新
    await window.aivicApi.update(invoiceTableIndex, selectedVerification.invoice.id, {
      invoiceStatus: '検証済み'
    });

    alert("修正を承認しました");
    allVerifications = await generateVerifications();
    renderVerifications(allVerifications);
    container.querySelector("#detail-panel").style.display = 'none';
  });

  // ===== 9. 修正却下ボタン =====
  container.querySelector("#btn-reject").addEventListener("click", async () => {
    if (!selectedVerification) return;
    const reason = container.querySelector("#correction-reason").value;
    if (!reason.trim()) {
      alert("却下理由を入力してください");
      return;
    }

    // 請求明細の検証ステータスを「却下」に更新
    for (const detail of selectedVerification.details) {
      await window.aivicApi.update(invoiceDetailTableIndex, detail.id, {
        verificationStatus: '却下',
        differenceReason: reason
      });
    }

    alert("修正を却下しました");
    allVerifications = await generateVerifications();
    renderVerifications(allVerifications);
    container.querySelector("#detail-panel").style.display = 'none';
  });

  // ===== 10. ダッシュボード遷移 =====
  container.querySelector("[data-testid='nav-dashboard']").addEventListener("click", () => {
    window.showScreen("scr-1781943762164");
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 契約=0, ユーザー=1, 契約履歴=2, 請求=3, 請求明細=4, 顧客=5, 操作ログ=6
  const contractTableIndex = 0;
  const userTableIndex = 1;
  const contractHistoryTableIndex = 2;

  let allContracts = [];
  let selectedContractId = null;
  let currentModalContractId = null;

  // 1. 再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#agreement-tbody");
    tbody.innerHTML = rows.map(r => {
      const statusClass = r.合意ステータス === "合意済" ? "status-approved" : 
                          r.合意ステータス === "却下" ? "status-rejected" : "status-pending";
      const statusColor = r.合意ステータス === "合意済" ? "#4ade80" : 
                          r.合意ステータス === "却下" ? "#ef4444" : "#f59e0b";
      return `
        <tr data-id="${r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.04)'" onmouseout="this.style.background='transparent'">
          <td style="padding: 8px 6px; color: var(--text); font-size: 12px;">${r.契約ID || ""}</td>
          <td style="padding: 8px 6px; color: var(--text); font-size: 12px;">${r.顧客名 || ""}</td>
          <td style="padding: 8px 6px; color: var(--text-muted); font-size: 12px; max-width: 140px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${r.変更内容 || ""}">${r.変更内容 || ""}</td>
          <td style="padding: 8px 6px; color: var(--text); font-size: 12px; text-align: center;">${r.合意期限 || ""}</td>
          <td style="padding: 8px 6px; text-align: center;">
            <span style="display: inline-block; padding: 4px 8px; background: ${statusColor}; color: #fff; border-radius: 3px; font-size: 11px; font-weight: 500;">${r.合意ステータス || "未設定"}</span>
          </td>
        </tr>
      `;
    }).join("");

    // 行クリックで詳細表示
    tbody.querySelectorAll("tr").forEach(tr => {
      tr.addEventListener("click", () => {
        selectedContractId = tr.dataset.id;
        const contract = allContracts.find(c => c.id === selectedContractId);
        if (contract) {
          showDetailPanel(contract);
        }
      });
    });
  }

  // 2. 詳細パネル表示
  function showDetailPanel(contract) {
    const detailPanel = container.querySelector("#detail-panel");
    const noSelection = container.querySelector("#no-selection");

    container.querySelector("#detail-contract-id").textContent = contract.契約ID || "";
    container.querySelector("#detail-customer-name").textContent = contract.顧客名 || "";
    container.querySelector("#detail-change-content").textContent = contract.変更内容 || "";
    container.querySelector("#detail-deadline").textContent = contract.合意期限 || "";

    // 通知先ユーザー一覧を表示
    const notificationUsers = contract.通知先ユーザー ? JSON.parse(contract.通知先ユーザー) : [];
    const userList = container.querySelector("#notification-users");
    userList.innerHTML = notificationUsers.map(user => {
      const statusColor = user.通知ステータス === "送信済" ? "#4ade80" : 
                          user.通知ステータス === "失敗" ? "#ef4444" : "#94a3b8";
      return `
        <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px; background: rgba(255,255,255,0.04); border-radius: 3px; margin-bottom: 4px;">
          <div>
            <div style="color: var(--text); font-weight: 500;">${user.ユーザー名 || ""}</div>
            <div style="font-size: 11px; color: var(--text-muted);">${user.メールアドレス || ""}</div>
          </div>
          <span style="padding: 3px 6px; background: ${statusColor}; color: #fff; border-radius: 2px; font-size: 10px; font-weight: 500;">${user.通知ステータス || "未送信"}</span>
        </div>
      `;
    }).join("");

    detailPanel.style.display = "block";
    noSelection.style.display = "none";
  }

  // 3. 初期データ読み込み
  async function loadInitialData() {
    const contracts = await window.aivicApi.list(contractTableIndex);
    if (contracts) {
      allContracts = contracts;
      renderRows(contracts);
    }
  }

  // 4. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const status = container.querySelector("#filter-status").value;
    const keyword = container.querySelector("#search-keyword").value.toLowerCase();

    let filtered = allContracts;
    if (status) {
      filtered = filtered.filter(c => c.合意ステータス === status);
    }
    if (keyword) {
      filtered = filtered.filter(c => 
        (c.契約ID || "").toLowerCase().includes(keyword) ||
        (c.顧客名 || "").toLowerCase().includes(keyword)
      );
    }
    renderRows(filtered);
  });

  // 5. 合意確認・却下ボタン（行レベル）
  container.addEventListener("click", async (e) => {
    // 合意確認ボタン
    if (e.target.closest(".confirm-btn")) {
      const contractId = e.target.closest(".confirm-btn").dataset.id;
      const contract = allContracts.find(c => c.id === contractId);
      if (contract) {
        currentModalContractId = contractId;
        container.querySelector("#modal-contract-id").textContent = contract.契約ID || "";
        container.querySelector("#modal-customer-name").textContent = contract.顧客名 || "";
        container.querySelector("#agreement-status").value = "";
        container.querySelector("#agreement-notes").value = "";
        container.querySelector("#agreement-modal").style.display = "flex";
      }
    }

    // 却下ボタン
    if (e.target.closest(".reject-btn")) {
      const contractId = e.target.closest(".reject-btn").dataset.id;
      if (confirm("この契約の合意を却下しますか？")) {
        await window.aivicApi.update(contractTableIndex, contractId, {
          合意ステータス: "却下",
          更新日時: new Date().toISOString()
        });
        showNotification("合意を却下しました");
        loadInitialData();
      }
    }
  });

  // 6. 再通知ボタン
  container.querySelector("#btn-resend-notification").addEventListener("click", async () => {
    if (!selectedContractId) return;
    const contract = allContracts.find(c => c.id === selectedContractId);
    if (!contract) return;

    // 通知ユーザーに再通知を送信
    const notificationUsers = contract.通知先ユーザー ? JSON.parse(contract.通知先ユーザー) : [];
    for (const user of notificationUsers) {
      // 実装: 通知送信ロジック（ここでは API 呼び出しを想定）
      // await window.aivicApi.save(notificationLogTableIndex, { ... });
    }
    showNotification("再通知を送信しました");
  });

  // 7. モーダル確認ボタン
  container.querySelector("#btn-modal-confirm").addEventListener("click", async () => {
    const status = container.querySelector("#agreement-status").value;
    const notes = container.querySelector("#agreement-notes").value;

    if (!status) {
      alert("合意ステータスを選択してください");
      return;
    }

    await window.aivicApi.update(contractTableIndex, currentModalContractId, {
      合意ステータス: status,
      備考: notes,
      更新日時: new Date().toISOString()
    });

    showNotification(`合意を${status === "合意済" ? "確認" : "却下"}しました`);
    container.querySelector("#agreement-modal").style.display = "none";
    loadInitialData();
  });

  // 8. モーダルキャンセルボタン
  container.querySelector("#btn-modal-cancel").addEventListener("click", () => {
    container.querySelector("#agreement-modal").style.display = "none";
  });

  // 9. 通知メッセージ表示
  function showNotification(message) {
    const msgEl = container.querySelector("#notification-message");
    msgEl.textContent = message;
    msgEl.style.display = "block";
    setTimeout(() => {
      msgEl.style.display = "none";
    }, 3000);
  }

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const invoiceTableIndex = 0;      // 請求テーブル
  const invoiceDetailTableIndex = 1; // 請求明細テーブル
  const contractTableIndex = 2;      // 契約テーブル
  const customerTableIndex = 3;      // 顧客テーブル

  // 現在表示中の請求ID（URL パラメータから取得、またはデモ用に最初の請求を使用）
  let currentInvoiceId = null;
  let currentInvoice = null;
  let currentContract = null;
  let currentCustomer = null;

  // 初期化: URL パラメータから請求ID取得
  function initializeInvoiceId() {
    const params = new URLSearchParams(window.location.search);
    currentInvoiceId = params.get('invoiceId');

    // デモ用: パラメータがなければ最初の請求を使用
    if (!currentInvoiceId && tables[invoiceTableIndex] && tables[invoiceTableIndex].records && tables[invoiceTableIndex].records.length > 0) {
      currentInvoiceId = tables[invoiceTableIndex].records[0].id;
    }
  }

  // 請求明細テーブルを再描画
  function renderInvoiceDetails(details) {
    const tbody = container.querySelector('#invoice-details-tbody');
    if (!details || details.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 12px;">明細がありません</td></tr>';
      return;
    }

    tbody.innerHTML = details.map(detail => {
      const verificationStatus = detail.検証ステータス || detail.verification_status || '未検証';
      const statusColor = verificationStatus === '検証済み' ? 'rgba(76,175,80,0.2)' : 
                         verificationStatus === '差異検出' ? 'rgba(255,152,0,0.2)' : 
                         'rgba(158,158,158,0.2)';

      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
          <td style="padding: 6px 8px; color: var(--text); font-size: 12px;">${detail.明細種別 || detail.line_type || '-'}</td>
          <td style="padding: 6px 8px; color: var(--text); font-size: 12px; max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${detail.説明 || detail.description || ''}">${detail.説明 || detail.description || '-'}</td>
          <td style="padding: 6px 8px; color: var(--text); text-align: right; font-size: 12px;">${detail.数量 || detail.quantity || 0}</td>
          <td style="padding: 6px 8px; color: var(--text); text-align: right; font-size: 12px;">¥${(detail.単価 || detail.unit_price || 0).toLocaleString()}</td>
          <td style="padding: 6px 8px; color: var(--text); text-align: right; font-size: 12px; font-weight: 600;">¥${(detail.金額 || detail.amount || 0).toLocaleString()}</td>
          <td style="padding: 6px 8px; text-align: center; font-size: 11px;">
            <span style="display: inline-block; padding: 2px 6px; background: ${statusColor}; color: var(--text); border-radius: 2px;">${verificationStatus}</span>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 請求情報を表示
  function displayInvoice(invoice) {
    if (!invoice) return;

    currentInvoice = invoice;

    // 請求基本情報
    container.querySelector('#invoice-id').textContent = invoice.id || '-';
    container.querySelector('#invoice-month').textContent = invoice.請求年月 || invoice.billing_month || '-';
    container.querySelector('#invoice-status').textContent = invoice.請求ステータス || invoice.status || '-';
    container.querySelector('#invoice-date').textContent = invoice.請求日 ? new Date(invoice.請求日).toLocaleDateString('ja-JP') : '-';
    container.querySelector('#due-date').textContent = invoice.支払期限日 ? new Date(invoice.支払期限日).toLocaleDateString('ja-JP') : '-';
    container.querySelector('#invoice-remarks').textContent = invoice.摘要 || invoice.remarks || '-';

    // 金額
    container.querySelector('#invoice-amount').textContent = `¥${(invoice.請求金額 || invoice.amount || 0).toLocaleString()}`;
    container.querySelector('#paid-amount').textContent = `¥${(invoice.支払済金額 || invoice.paid_amount || 0).toLocaleString()}`;

    // 契約情報を取得して表示
    if (invoice.契約ID || invoice.contract_id) {
      const contractId = invoice.契約ID || invoice.contract_id;
      const contract = (tables[contractTableIndex]?.records || []).find(c => c.id === contractId);
      if (contract) {
        displayContract(contract);

        // 顧客情報を取得
        if (contract.顧客企業ID || contract.customer_id) {
          const customerId = contract.顧客企業ID || contract.customer_id;
          const customer = (tables[customerTableIndex]?.records || []).find(cust => cust.id === customerId);
          if (customer) {
            container.querySelector('#customer-name').textContent = customer.顧客名 || customer.name || '-';
          }
        }
      }
    }

    // 請求明細を取得して表示
    const details = (tables[invoiceDetailTableIndex]?.records || []).filter(d => 
      d.請求ID === invoice.id || d.invoice_id === invoice.id
    );
    renderInvoiceDetails(details);
  }

  // 契約情報を表示
  function displayContract(contract) {
    if (!contract) return;

    currentContract = contract;

    container.querySelector('#contract-id').textContent = contract.id || '-';
    container.querySelector('#contract-start-date').textContent = contract.契約開始日 ? new Date(contract.契約開始日).toLocaleDateString('ja-JP') : '-';
    container.querySelector('#contract-end-date').textContent = contract.契約終了日 ? new Date(contract.契約終了日).toLocaleDateString('ja-JP') : '-';
    container.querySelector('#contract-amount').textContent = `¥${(contract.契約金額 || contract.amount || 0).toLocaleString()}`;
    container.querySelector('#contract-content').textContent = contract.契約内容 || contract.content || '-';
  }

  // 承認処理
  async function approveInvoice() {
    if (!currentInvoice) {
      alert('請求情報が読み込まれていません');
      return;
    }

    const comment = container.querySelector('#approval-comment').value;
    if (!comment.trim()) {
      alert('承認コメントを入力してください');
      return;
    }

    if (!confirm('この請求を承認してよろしいですか？')) return;

    const updated = await window.aivicApi.update(invoiceTableIndex, currentInvoice.id, {
      請求ステータス: '承認済',
      摘要: (currentInvoice.摘要 || '') + '\n[承認] ' + comment
    });

    if (updated) {
      alert('請求を承認しました');
      // 一覧画面へ戻る
      window.showScreen('scr-1781943828980');
    }
  }

  // 却下処理
  async function rejectInvoice() {
    if (!currentInvoice) {
      alert('請求情報が読み込まれていません');
      return;
    }

    const comment = container.querySelector('#approval-comment').value;
    if (!comment.trim()) {
      alert('却下理由を入力してください');
      return;
    }

    if (!confirm('この請求を却下してよろしいですか？')) return;

    const updated = await window.aivicApi.update(invoiceTableIndex, currentInvoice.id, {
      請求ステータス: '却下',
      摘要: (currentInvoice.摘要 || '') + '\n[却下] ' + comment
    });

    if (updated) {
      alert('請求を却下しました');
      // 一覧画面へ戻る
      window.showScreen('scr-1781943828980');
    }
  }

  // イベントリスナー登録
  container.querySelector('#btn-approve').addEventListener('click', approveInvoice);
  container.querySelector('#btn-reject').addEventListener('click', rejectInvoice);
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen('scr-1781943828980');
  });

  // 初期化
  initializeInvoiceId();

  // 初期データ表示
  if (currentInvoiceId && tables[invoiceTableIndex] && tables[invoiceTableIndex].records) {
    const invoice = tables[invoiceTableIndex].records.find(inv => inv.id === currentInvoiceId);
    if (invoice) {
      displayInvoice(invoice);
    } else {
      // API から取得を試みる
      window.aivicApi.list(invoiceTableIndex).then(invoices => {
        const inv = invoices.find(i => i.id === currentInvoiceId);
        if (inv) displayInvoice(inv);
      });
    }
  } else if (tables[invoiceTableIndex] && tables[invoiceTableIndex].records && tables[invoiceTableIndex].records.length > 0) {
    // デモ用: 最初の請求を表示
    displayInvoice(tables[invoiceTableIndex].records[0]);
  }
}
